#!/bin/bash
dnf update -y
dnf install -y nodejs
mkdir -p /opt/app
echo "" | base64 -d > /opt/app/app.js
echo "ewoibmFtZSI6ICJ2aWV3ZXItYXBwIiwKInZlcnNpb24iOiAiMS4wLjAiLAoibWFpbiI6ICJhcHAuanMiLAoiZGVwZW5kZW5jaWVzIjogewoiZXhwcmVzcyI6ICJeNC4xOS4yIiwKIkBhd3Mtc2RrL2NsaWVudC1zMyI6ICJeMy42MDAuMCIKfQp9Cg==" | base64 -d > /opt/app/package.json
cd /opt/app
npm install --omit=dev

cat > /etc/systemd/system/viewer.service << 'SERVICE'
[Unit]
Description=Viewer App
After=network.target

[Service]
Environment=BUCKET_NAME=itmo-gcm131-fileshare
Environment=AWS_REGION=us-east-2
Environment=PORT=3000
WorkingDirectory=/opt/app
ExecStart=/usr/bin/node /opt/app/app.js
Restart=always
User=ec2-user

[Install]
WantedBy=multi-user.target
SERVICE

chown -R ec2-user:ec2-user /opt/app
systemctl daemon-reload
systemctl enable viewer.service
systemctl start viewer.service
